package com.enterprise.procurement.persistence.mapper;
import com.enterprise.procurement.persistence.entity.*; import org.apache.ibatis.annotations.*;
@Mapper public interface CatalogMapper { @Select("SELECT id,name,reference_price,stock FROM sys_product WHERE id=#{id} AND active=1") ProductEntity product(@Param("id") Long id); @Select("SELECT id,name FROM sys_supplier WHERE id=#{id} AND active=1") SupplierEntity supplier(@Param("id") Long id); @Select("SELECT id,username,password,COALESCE(nickname,display_name) AS display_name,department_id FROM sys_user WHERE username=#{username} AND COALESCE(status,enabled)=1") SystemUserRow user(@Param("username") String username); @Select("SELECT r.code FROM sys_role r JOIN sys_user_role ur ON ur.role_id=r.id WHERE ur.user_id=#{userId}") java.util.List<String> roleCodes(@Param("userId") Long userId); }
